// Keywords to watch, and the domain you want Google's AI Overview to cite.
return [
  { json: { keyword: 'best crm for small business', country: 'us', domain: 'hubspot.com' } },
  { json: { keyword: 'crm software', country: 'gb', domain: 'hubspot.com' } },
];

// Builds one Slack message: for each keyword, whether Google shows an AI Overview,
// whether it cites your domain, and the first sources it cites.
const inputs = $('Keywords to watch').all();
const host = (u) => { try { return new URL(u).hostname.replace(/^www\./, ''); } catch { return ''; } };
const lines = $input.all().map((item, i) => {
  const { keyword, country, domain } = inputs[i].json;
  const { job, result } = item.json;
  if (!job || job.status !== 'completed') return `• *${keyword}* (${country}): request failed, not charged`;
  const ai = result.ai_overview;
  if (!ai) return `• *${keyword}* (${country}): no AI Overview`;
  const sources = [...new Set((ai.sources || []).map((s) => host(s.link)).filter(Boolean))];
  const cited = sources.some((h) => h === domain || h.endsWith('.' + domain));
  return `• *${keyword}* (${country}): AI Overview ${cited ? 'cites ' + domain + ' :white_check_mark:' : 'does not cite ' + domain + ' :x:'}  (sources: ${sources.slice(0, 4).join(', ') || 'none'})`;
});
return [{ json: { text: `*Google AI Overview report, ${new Date().toISOString().slice(0, 10)}*\n` + lines.join('\n') } }];
